import XCTest
import AVFoundation
@testable import HandyTools

/// Ogg Vorbis plays (File Opener tier 2): a made-up one-second 440 Hz tone encoded as Ogg Vorbis comes back as a
/// one-second .m4a, and the same file is accepted wherever an Ogg is (the Opus path falls back to Vorbis).
final class VorbisAudioTests: XCTestCase {
    private let ogg = Data(base64Encoded: "")!

    func testVorbisBecomesPlayableAudio() throws {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("tone.ogg")
        try ogg.write(to: url)
        let m4a = try XCTUnwrap(VorbisAudio.toM4A(url), "Vorbis wasn't decoded")
        let f = try AVAudioFile(forReading: m4a)
        XCTAssertEqual(Double(f.length) / f.fileFormat.sampleRate, 1.0, accuracy: 0.1)
        XCTAssertNotNil(Transcriber.oggOpusToM4A(url), "the voice tools' Ogg path should play Vorbis too")
        if case .quickLook = FileReaders.read(url) {} else { XCTFail("an .ogg should open to play") }
    }
}
